// Flatten each transcript into Sheet-ready columns (one row per video).
// Dataset rows with an `error` field (no captions, deleted or restricted
// videos) are skipped — the actor never charges for those anyway.
const CELL_LIMIT = 45000; // Google Sheets caps a cell at 50,000 chars; keep headroom.
const trunc = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);

const rows = [];
for (const { json: r } of $input.all()) {
  if (r.error) continue;
  const text = String(r.text || '');
  rows.push({
    json: {
      videoUrl: r.url || (r.videoId ? 'https://www.youtube.com/watch?v=' + r.videoId : ''),
      title: r.title || '',
      channel: r.channel || '',
      language: r.language || '',
      words: text ? text.trim().split(/\s+/).length : 0,
      transcript: trunc(text, CELL_LIMIT),
    },
  });
}
return rows;
